results = [
    {"tag": "easy", "pass": True}, {"tag": "easy", "pass": True},
    {"tag": "hard", "pass": False}, {"tag": "hard", "pass": True},
    {"tag": "hard", "pass": False},
]
by = {}
for r in results:
    by.setdefault(r["tag"], []).append(r["pass"])
for tag in sorted(by):
    print(tag, round(sum(by[tag]) / len(by[tag]), 2))
print("overall", round(sum(r["pass"] for r in results) / len(results), 2))

baseline = 0.90
tolerance = 0.02
def gate(rate):
    return "PASS" if rate >= baseline - tolerance else "FAIL"
for r in [0.95, 0.89, 0.87]:
    print(r, gate(r))
